using NUnit.Framework;

[TestFixture]
public class CountSignsTests
{
    [Test]
    public void Counts_Positive_Negative_And_Zero()
    {
        var result = CountSigns(new[] { -1, 0, 5, 7, -3 });
        Assert.That(result.positive, Is.EqualTo(2));
        Assert.That(result.negative, Is.EqualTo(2));
        Assert.That(result.zero, Is.EqualTo(1));
    }

    private (int positive, int negative, int zero) CountSigns(int[] nums)
    {
        int positive = 0, negative = 0, zero = 0;

        foreach (var num in nums)
        {
            if (num > 0)
                positive++;
            else if (num < 0)
                negative++;
            else
                zero++;
        }

        return (positive, negative, zero);
    }
}
